package com.smartseating.ui;

import com.smartseating.dao.*;
import com.smartseating.model.*;
import com.smartseating.service.PrintService;
import com.smartseating.util.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.util.List;

public class ExamFrame extends AppFrame {
    private final ExamDAO dao=new ExamDAO();private final DepartmentDAO deptDAO=new DepartmentDAO();private final SemesterDAO semDAO=new SemesterDAO();private final JTextField name=new JTextField(),date=new JTextField("2026-09-20"),time=new JTextField("10:00"),duration=new JTextField("120"),subject=new JTextField(),year=new JTextField("2025-26");private final JComboBox<String> type=new JComboBox<>(new String[]{"INTERNAL","EXTERNAL"}),status=new JComboBox<>(new String[]{"SCHEDULED","COMPLETED","CANCELLED"});private final JList<Department> departments=new JList<>();private final JList<Semester> semesters=new JList<>();private final DefaultListModel<Department> deptModel=new DefaultListModel<>();private final DefaultListModel<Semester> semModel=new DefaultListModel<>();private final JTable table=new JTable();private Exam selected;
    public ExamFrame(User user){super("Examination Management",user);UI.frame(this,1250,720);build();refresh();}
    private void build(){content.add(title("Examination Management"),BorderLayout.NORTH);JPanel form=UI.formPanel();UI.addField(form,0,"Exam Name",name);UI.addField(form,1,"Exam Type",type);UI.addField(form,2,"Exam Date (yyyy-MM-dd)",date);UI.addField(form,3,"Start Time (HH:mm)",time);UI.addField(form,4,"Duration (minutes)",duration);UI.addField(form,5,"Subject",subject);UI.addField(form,6,"Academic Year",year);UI.addField(form,7,"Status",status);departments.setModel(deptModel);departments.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);semesters.setModel(semModel);semesters.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);UI.addField(form,8,"Departments",UI.scroll(departments));UI.addField(form,9,"Semesters",UI.scroll(semesters));JPanel a=new JPanel(new GridLayout(2,3,7,7));a.setOpaque(false);JButton add=button("ADD EXAM",UI.TEAL),update=button("UPDATE",UI.BLUE),del=button("DELETE",new Color(190,66,66)),clear=button("CLEAR",UI.MUTED),print=button("PRINT",UI.ORANGE);for(JButton b:new JButton[]{add,update,del,clear,print})a.add(b);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=10;g.gridwidth=2;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(14,6,6,6);form.add(a,g);content.add(white(form),BorderLayout.WEST);UI.tableStyle(table);content.add(white(UI.scroll(table)),BorderLayout.CENTER);try{for(Department d:deptDAO.findAll())deptModel.addElement(d);for(Semester s:semDAO.findAll())semModel.addElement(s);}catch(Exception ex){error(ex);}add.addActionListener(e->save());update.addActionListener(e->update());del.addActionListener(e->delete());clear.addActionListener(e->clear());print.addActionListener(e->PrintService.print("Exam Details",text()));table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0)load();});}
    private Exam read(){if(departments.getSelectedValuesList().isEmpty())throw new IllegalArgumentException("Select at least one department.");if(semesters.getSelectedValuesList().isEmpty())throw new IllegalArgumentException("Select at least one semester.");return new Exam(0,Validation.text(name.getText(),"Exam name"),(String)type.getSelectedItem(),Validation.date(date.getText()),Validation.time(time.getText()),Validation.positive(duration.getText(),"Duration"),Validation.text(subject.getText(),"Subject"),Validation.text(year.getText(),"Academic year"),(String)status.getSelectedItem());}private List<String> depCodes(){return departments.getSelectedValuesList().stream().map(Department::getCode).toList();}private List<String> semCodes(){return semesters.getSelectedValuesList().stream().map(Semester::getNumber).toList();}private void save(){try{Exam x=read();dao.save(x,depCodes(),semCodes());clear();refresh();}catch(Exception ex){error(ex);}}private void update(){try{if(selected==null)throw new IllegalArgumentException("Select an examination first.");Exam x=read();x.setId(selected.getId());dao.update(x,depCodes(),semCodes());clear();refresh();}catch(Exception ex){error(ex);}}private void delete(){try{if(selected==null)throw new IllegalArgumentException("Select an examination first.");if(confirm("Delete exam and any saved seating for it?")){dao.delete(selected.getId());clear();refresh();}}catch(Exception ex){error(ex);}}private void load(){try{selected=dao.findById((int)table.getValueAt(table.getSelectedRow(),0));name.setText(selected.getName());type.setSelectedItem(selected.getType());date.setText(selected.getDate().toString());time.setText(selected.getStartTime().toString().substring(0,5));duration.setText(String.valueOf(selected.getDurationMinutes()));subject.setText(selected.getSubject());year.setText(selected.getAcademicYear());status.setSelectedItem(selected.getStatus());List<String> ds=dao.selectedDepartments(selected.getId()),ss=dao.selectedSemesters(selected.getId());int[] di=java.util.stream.IntStream.range(0,deptModel.size()).filter(i->ds.contains(deptModel.get(i).getCode())).toArray();int[] si=java.util.stream.IntStream.range(0,semModel.size()).filter(i->ss.contains(semModel.get(i).getNumber())).toArray();departments.setSelectedIndices(di);semesters.setSelectedIndices(si);}catch(Exception ex){error(ex);}}private void clear(){selected=null;name.setText("");date.setText("2026-09-20");time.setText("10:00");duration.setText("120");subject.setText("");departments.clearSelection();semesters.clearSelection();table.clearSelection();}private void refresh(){try{DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Exam","Type","Date","Time","Subject","Status"},0);for(Exam e:dao.findAll())m.addRow(new Object[]{e.getId(),e.getName(),e.getType(),e.getDate(),e.getStartTime(),e.getSubject(),e.getStatus()});table.setModel(m);UI.tableStyle(table);}catch(Exception ex){error(ex);}}private String text(){StringBuilder b=new StringBuilder("EXAM DETAILS\n\n");for(int i=0;i<table.getRowCount();i++)b.append(table.getValueAt(i,1)).append(" | ").append(table.getValueAt(i,2)).append(" | ").append(table.getValueAt(i,3)).append(" ").append(table.getValueAt(i,4)).append(" | ").append(table.getValueAt(i,5)).append("\n");return b.toString();}
}
